  "admin.categories.stat.total": { en: "Total Categories", ar: "إجمالي الفئات", ur: "کل زمرے" , es: "Total Categorías", fr: "Total des catégories", de: "Gesamtkategorien", hi: "कुल श्रेणियाँ", zh: "类别共计", pt: "Total Categorias", tr: "Toplam Kategoriler"},
